{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyonthreshold.invalid/schema/incident-report-1.0.0.json",
  "title": "Halcyon Threshold Incident Evidence Report",
  "description": "Design-stage reporting profile. Validation is not a legal compliance or truth determination.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version", "report_id", "revision", "report_stage", "supersedes",
    "change_summary", "reported_at", "reporting_organization", "incident_status",
    "status_basis", "status_evidence_refs", "incident", "timeline", "systems",
    "claims", "harms", "controls", "containment_actions", "corrective_actions",
    "evidence", "notifications", "open_unknowns", "next_update_at"
  ],
  "properties": {
    "schema_version": {"const": "1.0.0"},
    "report_id": {"$ref": "#/$defs/id"},
    "revision": {"type": "integer", "minimum": 1},
    "report_stage": {"enum": ["initial", "interim", "final"]},
    "supersedes": {"type": ["string", "null"], "minLength": 1},
    "change_summary": {"type": "string", "minLength": 1},
    "reported_at": {"$ref": "#/$defs/timestamp"},
    "reporting_organization": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "contact_role", "contact_email"],
      "properties": {
        "name": {"type": "string", "minLength": 1},
        "contact_role": {"type": "string", "minLength": 1},
        "contact_email": {"type": "string", "format": "email"}
      }
    },
    "incident_status": {"enum": ["ongoing", "contained", "resolved", "unknown"]},
    "status_basis": {"type": "string", "minLength": 1},
    "status_evidence_refs": {"$ref": "#/$defs/evidenceRefs"},
    "incident": {
      "type": "object",
      "additionalProperties": false,
