from __future__ import annotations

import json
from pathlib import Path
import unittest

ROOT = Path(__file__).resolve().parents[1]

try:
    from jsonschema import Draft202012Validator, FormatChecker
except ImportError:
    Draft202012Validator = None
    FormatChecker = None


@unittest.skipIf(Draft202012Validator is None, "optional jsonschema dependency is not installed")
class StandardSchemaTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.schema = json.loads((ROOT / "schema" / "incident-report.schema.json").read_text(encoding="utf-8"))
        cls.validator = Draft202012Validator(cls.schema, format_checker=FormatChecker())

    def test_schema_itself_is_valid(self) -> None:
        Draft202012Validator.check_schema(self.schema)

    def test_valid_fixtures_conform(self) -> None:
        for name in ("complete-report.json", "near-miss-report.json"):
            with self.subTest(name=name):
                document = json.loads((ROOT / "examples" / name).read_text(encoding="utf-8"))
                self.assertEqual([], list(self.validator.iter_errors(document)))

    def test_incomplete_fixture_does_not_conform(self) -> None:
        document = json.loads((ROOT / "examples" / "incomplete-report.json").read_text(encoding="utf-8"))
        self.assertNotEqual([], list(self.validator.iter_errors(document)))


if __name__ == "__main__":
    unittest.main()
